def replace_once(path: Path, old: str, new: str, label: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one source anchor in {path}, found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


def insert_after_once(path: Path, anchor: str, addition: str, label: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(anchor)
    if count != 1:
        raise RuntimeError(f"{label}: expected one source anchor in {path}, found {count}")
    path.write_text(text.replace(anchor, anchor + "\n\n" + addition, 1), encoding="utf-8")


def git_output(root: Path, *args: str) -> str:
    return subprocess.check_output(["git", *args], cwd=root, text=True).strip()


def verify_base(root: Path, skip: bool) -> None:
    if skip:
        return
    try:
        head = git_output(root, "rev-parse", "HEAD")
        subprocess.check_call(
            ["git", "merge-base", "--is-ancestor", BASE_COMMIT, head],
            cwd=root,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except Exception as exc:
        raise RuntimeError(
            f"repository must contain V5 commit {BASE_COMMIT} as an ancestor; "
            "use --skip-git-check only if intentional"
        ) from exc


def apply(root: Path) -> None:
    new_module = root / "lib/video_prompt_compilers/h3_director_compiler.py"
    new_module.parent.mkdir(parents=True, exist_ok=True)
    new_module.write_text(DIRECTOR_COMPILER, encoding="utf-8")

    execution = root / "lib/reference_video/h3_prompt_execution.py"
    execution.write_text(EXECUTION_SEAM, encoding="utf-8")

    legacy = root / "lib/video_prompt_compilers/h3_prompt_compiler.py"
    if "_render_inline_dialogues(" not in legacy.read_text(encoding="utf-8"):
        insert_after_once(
            legacy,
            LEGACY_REPLACE_ANCHOR,
            INLINE_DIALOGUE_HELPER.rstrip(),
            "legacy-inline-dialogue-helper",
        )
    replace_once(legacy, OLD_COMPILE, NEW_COMPILE, "legacy-inline-dialogue-body")
    replace_once(legacy, OLD_DETAIL, NEW_DETAIL, "legacy-shot-preservation")

    replace_once(root / "lib/reference_video/prompt_preview.py",
                 PREVIEW_OLD, PREVIEW_NEW, "preview-generation-mode")
    replace_once(root / "server/services/reference_video_tasks.py",
                 TASKS_OLD, TASKS_NEW, "runtime-unit-id")

    svc = root / "server/services/reference_video_prompt_preview.py"
    replace_once(svc, SVC_SIG_OLD, SVC_SIG_NEW, "preview-canonical-signature")
    replace_once(svc, SVC_PAY_OLD, SVC_PAY_NEW, "preview-canonical-payload")
    replace_once(svc, SVC_CALL_OLD, SVC_CALL_NEW, "preview-unit-id")

    router = root / "server/routers/reference_videos.py"
    replace_once(router, ROUTER_FIELD_OLD, ROUTER_FIELD_NEW, "rest-canonical-field")
    replace_once(router, ROUTER_PREVIEW_OLD, ROUTER_PREVIEW_NEW, "rest-preview-canonical")
    replace_once(router, ROUTER_PAYLOAD_OLD, ROUTER_PAYLOAD_NEW, "rest-generate-canonical")

    tool = root / "server/tool_runtime.py"
    replace_once(tool, TOOL_FIELD_OLD, TOOL_FIELD_NEW, "tool-preview-canonical-field")
    replace_once(tool, TOOL_FORCE_OLD, TOOL_FORCE_NEW, "tool-preview-force-route")
    replace_once(tool, TOOL_PASS_OLD, TOOL_PASS_NEW, "tool-preview-canonical-pass")

    sdk_preview = root / "server/agent_runtime/sdk_tools/prompt_preview.py"
    replace_once(sdk_preview, SDK_SCHEMA_OLD, SDK_SCHEMA_NEW, "sdk-preview-canonical-schema")

    remote_mcp = root / "server/remote_mcp.py"
    replace_once(remote_mcp, REMOTE_SIG_OLD, REMOTE_SIG_NEW, "remote-mcp-canonical-signature")
    replace_once(remote_mcp, REMOTE_PASS_OLD, REMOTE_PASS_NEW, "remote-mcp-canonical-pass")

    ts = root / "frontend/src/types/reference-video.ts"
    replace_once(ts, TS_FIELD_OLD, TS_FIELD_NEW, "frontend-canonical-field")
    replace_once(ts, TS_PREVIEW_OLD, TS_PREVIEW_NEW, "frontend-generation-mode")
    replace_once(root / "frontend/src/components/canvas/reference/PromptPreviewDialog.tsx",
                 DIALOG_OLD, DIALOG_NEW, "preview-dialog-mode")

    tests = root / "tests/unit/test_h3_v6_director.py"
    tests.write_text(V6_TESTS, encoding="utf-8")


def run_tests(root: Path) -> None:
    commands = [
        ["uv", "run", "pytest",
         "tests/unit/test_h3_prompt_compiler.py",
         "tests/unit/test_h3_v6_director.py",
         "-q"],
        ["uv", "run", "ruff", "check",
         "lib/video_prompt_compilers/h3_director_compiler.py",
         "lib/video_prompt_compilers/h3_prompt_compiler.py",
         "lib/reference_video/h3_prompt_execution.py",
         "lib/reference_video/prompt_preview.py",
         "server/services/reference_video_prompt_preview.py",
         "server/services/reference_video_tasks.py",
         "server/routers/reference_videos.py",
         "server/tool_runtime.py",
         "server/agent_runtime/sdk_tools/prompt_preview.py",
         "server/remote_mcp.py"],
    ]
    for cmd in commands:
        print("+", " ".join(cmd))
        subprocess.check_call(cmd, cwd=root)


def main() -> int:
    parser = argparse.ArgumentParser(description="Apply ArcReel H3 V6 fixes")
    parser.add_argument("repo", type=Path)
    parser.add_argument("--test", action="store_true")
    parser.add_argument("--skip-git-check", action="store_true")
    args = parser.parse_args()

    root = args.repo.resolve()
    verify_base(root, args.skip_git_check)
    apply(root)
    if args.test:
        run_tests(root)
    print("V6 patch applied.")
    print("Review with: git diff --check && git diff")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())